define("local_sentientia_challenge/challenge_actions", [
    "core_form/modalform",
    "core/str",
    "core/notification",
    "core/ajax"
], function(ModalForm, Str, Notification, Ajax) {
    "use strict";

    var getString = Str.get_string;

    function openChallengeForm(challengeid, returnFocus) {
        var titleKey = challengeid === 0 ? "btn_create" : "btn_edit";
        return getString(titleKey, "local_sentientia_challenge").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_sentientia_challenge\\form\\edit_challenge_dynamic_form",
                args: {challengeid: challengeid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function() {
                getString(challengeid === 0 ? "challenge_created" : "challenge_updated",
                    "local_sentientia_challenge", "").then(function(msg) {
                    Notification.addNotification({message: msg, type: "success"});
                    window.location.reload();
                    return null;
                }).catch(Notification.exception);
            });
            modalForm.show();
            return null;
        });
    }

    function join(challengeid, returnFocus) {
        return getString("joined_challenge", "local_sentientia_challenge").then(function(success) {
            Ajax.call([{
                methodname: "local_sentientia_challenge_join_challenge",
                args: {challengeid: challengeid}
            }])[0].then(function() {
                Notification.addNotification({message: success, type: "success"});
                window.location.reload();
                return null;
            }).catch(Notification.exception);
            if (returnFocus) setTimeout(function() { returnFocus.focus(); }, 100);
            return null;
        });
    }

    function leave(challengeid, returnFocus) {
        return Promise.all([
            getString("btn_leave", "local_sentientia_challenge"),
            getString("btn_leave", "local_sentientia_challenge"),
            getString("continue", "core"),
            getString("left_challenge", "local_sentientia_challenge")
        ]).then(function(strs) {
            var title = strs[0], message = strs[1], ok = strs[2], success = strs[3];
            Notification.confirm(title, message + "?", ok, null, function() {
                Ajax.call([{
                    methodname: "local_sentientia_challenge_leave_challenge",
                    args: {challengeid: challengeid}
                }])[0].then(function() {
                    Notification.addNotification({message: success, type: "success"});
                    window.location.reload();
                    return null;
                }).catch(Notification.exception);
            });
            if (returnFocus) setTimeout(function() { returnFocus.focus(); }, 100);
            return null;
        });
    }

    function confirmDelete(challengeid, name, returnFocus) {
        return Promise.all([
            getString("btn_delete", "local_sentientia_challenge"),
            getString("challenge_deleted", "local_sentientia_challenge", name),
            getString("delete", "core"),
            getString("challenge_deleted", "local_sentientia_challenge", name)
        ]).then(function(strs) {
            var title = strs[0], message = strs[1], label = strs[2], success = strs[3];
            Notification.deleteCancelPromise(title, message, label, returnFocus).then(function() {
                Ajax.call([{
                    methodname: "local_sentientia_challenge_delete_challenge",
                    args: {id: challengeid}
                }])[0].then(function() {
                    Notification.addNotification({message: success, type: "success"});
                    window.location.reload();
                    return null;
                }).catch(Notification.exception);
                return true;
            }, function() { return null; });
            return null;
        });
    }

    function handleClick(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        var action = trigger.dataset.action;
        var challengeid = parseInt(trigger.dataset.challengeid || "0", 10);
        var name = trigger.dataset.name || "";
        if (action === "create-challenge") { event.preventDefault(); openChallengeForm(0, trigger); }
        else if (action === "edit-challenge") { event.preventDefault(); openChallengeForm(challengeid, trigger); }
        else if (action === "delete-challenge") { event.preventDefault(); confirmDelete(challengeid, name, trigger); }
        else if (action === "join-challenge") { event.preventDefault(); join(challengeid, trigger); }
        else if (action === "leave-challenge") { event.preventDefault(); leave(challengeid, trigger); }
    }

    function reloadTable(mountId, extraArgs) {
        var mount = document.getElementById(mountId);
        if (!mount) return;
        mount.dataset.extraArgs = JSON.stringify(extraArgs);
        mount.dispatchEvent(new CustomEvent("airpay-datatable:reload", {bubbles: true}));
    }

    function debounce(fn, ms) {
        var t;
        return function() {
            var ctx = this, args = arguments;
            clearTimeout(t);
            t = setTimeout(function() { fn.apply(ctx, args); }, ms || 250);
        };
    }

    function wireIndexFilters() {
        var search = document.getElementById("airpay-challenge-search");
        var status = document.getElementById("airpay-challenge-status");
        if (!search || !status) return;
        var update = function() {
            reloadTable("airpay-challenge-table", {
                search: search.value.trim(),
                status: status.value || "active"
            });
        };
        search.addEventListener("input", debounce(update, 250));
        status.addEventListener("change", update);
    }

    function wireLeaderboardFilters(mountId) {
        var challenge = document.getElementById("airpay-challenge-lb-challenge");
        var tenant = document.getElementById("airpay-challenge-lb-tenant");
        var update = function() {
            reloadTable(mountId, {
                challengeid: parseInt((challenge && challenge.value) || "0", 10),
                tenantmode: (tenant && tenant.value) || "mine"
            });
        };
        if (challenge) challenge.addEventListener("change", update);
        if (tenant)    tenant.addEventListener("change", update);
    }

    return {
        init: function(config) {
            config = config || {};
            document.addEventListener("click", handleClick);
            if (config.page === "index") {
                wireIndexFilters();
            } else if (config.page === "leaderboard") {
                wireLeaderboardFilters("airpay-challenge-leaderboard-global-table");
            }
        }
    };
});
